const fetch = require('node-fetch');
const fs = require('fs');
const path = require('path');

const API_KEY = process.env.CROSSMINT_API_KEY;
const API_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const OUTPUT_FILE = '/home/user/mint_response.json';

async function mintNFT() {
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'x-api-key': API_KEY,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        recipient: 'email:test@example.com:polygon-amoy',
        metadata: {
          name: 'Welcome NFT',
          description: 'A welcome gift',
          image: 'https://example.com/nft.png',
        },
      }),
    });

    const responseData = await response.json();

    // Write response to file
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(responseData, null, 2));

    if (!response.ok) {
      console.error(`API request failed with status ${response.status}`);
      console.error('Error response written to', OUTPUT_FILE);
      process.exit(1);
    }

    console.log('NFT minted successfully!');
    console.log('Response written to', OUTPUT_FILE);
  } catch (error) {
    // Handle network errors or other exceptions
    const errorResponse = {
      error: error.message,
      type: error.constructor.name,
    };
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(errorResponse, null, 2));
    console.error('Error occurred:', error.message);
    console.error('Error response written to', OUTPUT_FILE);
    process.exit(1);
  }
}

mintNFT();

